// Hand-written `ofetch` stub: `ofetch` and `$fetch` are the same client,
// called with an address and options, and `create` makes one holding a base
// and the hooks it runs before every request.

export interface FetchOptions {
  method?: string;
  body?: unknown;
  baseURL?: string;
  onRequest?: (context: FetchContext) => void | Promise<void>;
}

export interface FetchContext {
  request: string;
  options: FetchOptions;
}

export interface $Fetch {
  <T = unknown>(url: string, options?: FetchOptions): Promise<T>;
  raw<T = unknown>(url: string, options?: FetchOptions): Promise<T>;
  create(defaults: FetchOptions): $Fetch;
}

export declare const ofetch: $Fetch;
export declare const $fetch: $Fetch;
